    m_->w[0][1][0] = m_->index_ == 0 ? 0.0 : m_->w[1][0][0];
    m_->w[0][2][0] = m_->index_ == 0 ? 0.0 : m_->w[1][1][0];
    m_->z[0][0][0] = m_->W[0][0] * m_->w[0][0][0] + m_->W[0][1] * m_->w[0][1][0] + m_->W[0][2] * m_->w[0][2][0];
    m_->z[0][1][0] = m_->W[1][0] * m_->w[0][0][0] + m_->W[1][1] * m_->w[0][1][0] + m_->W[1][2] * m_->w[0][2][0];
